/**
 * GET /api/openapi.json — the API description for the in-app documentation.
 *
 * Session-authenticated (like the rest of `/api`), so the docs page can load it
 * without holding an API credential. The document itself is generated by the
 * evaluation service from its own FastAPI routes — see `router/public.py`.
 */
import { json } from '@sveltejs/kit';
import { SERVICES } from '$lib/server/services';
import type { RequestHandler } from './$types';

export const GET: RequestHandler = async () => {
	try {
		const resp = await fetch(`${SERVICES.evaluation}/v1/public/openapi.json`);
		return json(await resp.json(), { status: resp.status });
	} catch (err) {
		return json(
			{
				error: 'upstream_unavailable',
				detail: `Pipeline nicht erreichbar: ${err instanceof Error ? err.message : String(err)}`
			},
			{ status: 502 }
		);
	}
};
